function renderTripHeader(t,b){return`<section class="trip-header"><div class="trip-header-stats">${hstat("Inicio",formatDayDate(t.startDate))}${hstat("Fin",formatDayDate(t.endDate))}${hstat("Días",t.days.length)}${hstat("Personas",t.travelers.length||"—")}${hstat("Estimado",money(b.estimated,"EUR"))}${hstat("Gastado",money(b.spent,"EUR"))}</div>${t.travelers.length?`<div class="meta header-people">👥 ${esc(travelerNames(t).join(", "))}</div>`:""}<div class="header-label">Días en Horario</div><div class="day-chips">${t.days.map((d,i)=>`<button class="day-chip" data-action="go-day" data-id="${d.id}"><strong>Día ${i+1}</strong> ${esc(formatDayDate(d.date))}</button>`).join("")}</div>${miniChart(b)}${renderClocks(t)}<div class="btn-row header-actions"><button class="secondary-btn" data-action="edit-trip">✏️ Fechas, zona horaria y datos del viaje</button></div></section>`}
function miniChart(b){const parts=Object.entries(b.byCategory).filter(([,x])=>x.spent>0),tot=parts.reduce((s,[,x])=>s+x.spent,0);if(!tot)return'<div class="header-label">Gastos por tipo</div><div class="meta">Sin gastos todavía</div>';return`<div class="header-label">Gastos por tipo</div><div class="mini-chart" role="img" aria-label="Gastos por tipo">${parts.map(([c,x])=>`<span class="category-${CATEGORIES[c].className}" style="width:${(x.spent/tot*100).toFixed(1)}%" title="${attr(c)}: ${attr(money(x.spent,"EUR"))}"></span>`).join("")}</div><div class="mini-legend">${parts.map(([c,x])=>`<span class="category-${CATEGORIES[c].className}"><i></i>${CATEGORIES[c].icon} ${esc(c)} ${esc(money(x.spent,"EUR"))}</span>`).join("")}</div>`}
// ---- Zona horaria ----
function cityName(t){return String(t.destination||"").split(/,| y /)[0].trim()||"Destino"}
function clockText(tz){try{return new Intl.DateTimeFormat("es-ES",{timeZone:tz,hour:"2-digit",minute:"2-digit"}).format(new Date())}catch{return"--:--"}}
function tzOffsetMin(tz,date){const p=Object.fromEntries(new Intl.DateTimeFormat("en-US",{timeZone:tz,hourCycle:"h23",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit"}).formatToParts(date).map(x=>[x.type,x.value]));return Math.round((Date.UTC(+p.year,+p.month-1,+p.day,+p.hour%24,+p.minute,+p.second)-Math.floor(date.getTime()/1000)*1000)/60000)}
function zonedToUTC(date,time,tz){const[y,m,d]=date.split("-").map(Number),[hh,mm]=time.split(":").map(Number),guess=Date.UTC(y,m-1,d,hh,mm||0);let r=guess-tzOffsetMin(tz,new Date(guess))*60000;r=guess-tzOffsetMin(tz,new Date(r))*60000;return new Date(r)}
function renderClocks(t){if(!t.timeZone||t.timeZone==="Europe/Madrid")return"";const now=new Date(),diff=tzOffsetMin(t.timeZone,now)-tzOffsetMin("Europe/Madrid",now);if(!diff)return"";const h=diff/60;return`<div class="clocks"><span>🕐 ${esc(cityName(t))} <strong data-tz="${attr(t.timeZone)}">${clockText(t.timeZone)}</strong></span><span>Madrid <strong data-tz="Europe/Madrid">${clockText("Europe/Madrid")}</strong></span><small>${h>0?"+":"−"}${Math.abs(h)} h respecto a Madrid</small></div>`}
async function omGeocode(name){name=String(name||"").trim();if(!name)return null;const key=`wanderlog.omgeo.${name.toLowerCase()}`,c=loadJSON(key,null);if(c)return c;const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(name)}&count=1&language=es&format=json`);if(!r.ok)return null;const x=(await r.json()).results?.[0];if(!x)return null;const out={name:x.name,lat:x.latitude,lng:x.longitude,timezone:x.timezone};try{localStorage.setItem(key,JSON.stringify(out))}catch{}return out}
async function ensureTimeZone(t){if(t.timeZone||!state.online||state.tzTried?.has(t.id))return;(state.tzTried||=new Set).add(t.id);try{const g=await omGeocode(cityName(t));if(g?.timezone&&validTZ(g.timezone)){t.timeZone=g.timezone;saveTrip(t);if(currentTrip()===t&&!state.modal)render()}}catch(e){console.warn("Zona horaria",e)}}
// ---- Previsión del tiempo (Open-Meteo) ----
function weatherTarget(t,d){if(d.weatherPlace)return{label:d.weatherPlace,place:d.weatherPlace,kind:"name"};const s=stayForDay(t,d)||departingStay(t,d);if(s&&(s.lat!=null||s.mapQuery||s.location))return{label:s.title,place:s.mapQuery||s.location,lat:s.lat,lng:s.lng,kind:"address"};return{label:cityName(t),place:cityName(t),kind:"name"}}
function weatherSlot(t,d){return`<div class="weather" data-weather-day="${d.id}">${weatherHtml(t,d)}</div>`}
function weatherHtml(t,d){const w=state.wx[`${t.id}|${d.id}`],credit='<a href="https://open-meteo.com/" target="_blank" rel="noopener">Weather data by Open-Meteo</a>';if(!w){queueMicrotask(()=>loadWeather(t,d));return'<span class="muted">Cargando previsión…</span>'}const place=`<span class="wx-place">📍 ${esc(w.label)} · ${credit}</span>`;if(w.status==="loading")return`<span class="muted">Cargando previsión…</span>${place}`;if(w.status==="range")return`<span class="muted">Previsión disponible desde el ${esc(shortDay(w.from))}</span>${place}`;if(w.status==="past")return`<span class="muted">Sin previsión para fechas pasadas</span>${place}`;if(w.status==="error")return`<span class="muted">Previsión no disponible</span>${place}`;const x=w.data||{},[ic,tx]=WMO[x.code]||["🌡️","Previsión"];return`<span class="wx-main">${ic} ${esc(tx)}</span>${x.max!=null?`<span>${Math.round(x.max)}° / ${Math.round(x.min)}°</span>`:""}${x.rain!=null?`<span>💧 ${esc(x.rain)}%</span>`:""}${w.stale?`<span class="muted">(guardada ${esc(new Intl.DateTimeFormat("es-ES",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}).format(w.ts))})</span>`:""}${place}`}
function paintWeather(t,d){document.querySelectorAll(`[data-weather-day="${d.id}"]`).forEach(el=>el.innerHTML=weatherHtml(t,d))}
async function loadWeather(t,d){const key=`${t.id}|${d.id}`;if(state.wx[key])return;const today=localISO(new Date()),tg=weatherTarget(t,d);if(d.date>addDays(today,15)){state.wx[key]={status:"range",label:tg.label,from:addDays(d.date,-15)};return paintWeather(t,d)}if(d.date<addDays(today,-60)){state.wx[key]={status:"past",label:tg.label};return paintWeather(t,d)}state.wx[key]={status:"loading",label:tg.label};
 try{let coords=tg.lat!=null&&Number.isFinite(+tg.lat)&&+tg.lat?[+tg.lat,+tg.lng]:null;if(!coords){if(tg.kind==="name"){const g=await omGeocode(tg.place);coords=g?[g.lat,g.lng]:null}else coords=await geocodePlace(stripMapUrl(tg.place)).catch(()=>null)}if(!coords){const g=await omGeocode(cityName(t)).catch(()=>null);if(g){coords=[g.lat,g.lng];state.wx[key].label=tg.label=cityName(t)}}if(!coords)throw Error("Lugar no encontrado");
  const ck=`wanderlog.wx.${(+coords[0]).toFixed(2)},${(+coords[1]).toFixed(2)},${d.date}`,cached=loadJSON(ck,null);let data=cached?.data,ts=cached?.ts;
  if(!cached||Date.now()-cached.ts>3*3600e3){try{if(!state.online)throw Error("Sin conexión");const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${coords[0]}&longitude=${coords[1]}&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto&start_date=${d.date}&end_date=${d.date}`);if(!r.ok)throw Error("HTTP "+r.status);const dl=(await r.json()).daily||{};data={code:dl.weather_code?.[0],max:dl.temperature_2m_max?.[0],min:dl.temperature_2m_min?.[0],rain:dl.precipitation_probability_max?.[0]};ts=Date.now();try{localStorage.setItem(ck,JSON.stringify({ts,data}))}catch{}}catch(e){if(!cached)throw e}}
  state.wx[key]={status:"ok",label:tg.label,data,ts,stale:Date.now()-ts>3*3600e3}}catch(e){console.warn("Tiempo",e);state.wx[key]={status:"error",label:tg.label}}paintWeather(t,d)}
// ---- Documentos de Drive ----
function drivePreviewUrl(u){try{const x=new URL(u);if(/(^|\.)drive\.google\.com$/.test(x.hostname)){const id=x.pathname.match(/\/file\/d\/([^/]+)/)?.[1]||x.searchParams.get("id");return id?`https://drive.google.com/file/d/${encodeURIComponent(id)}/preview`:null}if(x.hostname==="docs.google.com"){const m=x.pathname.match(/^\/(document|spreadsheets|presentation)\/d\/([^/]+)/);return m?`https://docs.google.com/${m[1]}/d/${encodeURIComponent(m[2])}/preview`:null}}catch{}return null}
function drivePreview(url,title){if(!url)return"";const p=drivePreviewUrl(url);return`<div class="doc-preview">${p&&state.online?`<iframe src="${attr(p)}" loading="lazy" title="Vista previa: ${attr(title)}"></iframe>`:""}<div class="link-row"><a href="${safeUrl(url)}" target="_blank" rel="noopener">📄 ${isDriveUrl(url)?"Abrir en Drive":"Abrir documento"}</a></div></div>`}
// ---- Secciones nuevas de Info ----
function renderTravelers(t){return t.travelers.length?`<div class="compact-list">${t.travelers.map(p=>`<div class="compact-card"><div class="compact-card-head"><span>👤</span><strong>${esc(p.name)}</strong><button class="mini-btn" data-action="edit-traveler" data-id="${p.id}" aria-label="Editar" title="Editar">✏️</button></div></div>`).join("")}</div>`:'<div class="empty">Sin personas. Añádelas con ＋.</div>'}
function renderInsurances(t){return`<div class="compact-list">${t.insurances.map(i=>`<details class="details-block"><summary><span>🛡️ ${esc(i.insurer)}</span>${i.policyNumber?`<span class="badge">${esc(i.policyNumber)}</span>`:""}<button class="mini-btn" data-action="edit-insurance" data-id="${i.id}" aria-label="Editar" title="Editar">✏️</button></summary><div class="details-content">${esc([i.policyNumber&&`Póliza: ${i.policyNumber}`,(i.startDate||i.endDate)&&`Cobertura: ${i.startDate?shortDay(i.startDate):"…"} → ${i.endDate?shortDay(i.endDate):"…"}`,i.notes].filter(Boolean).join("\n"))}${i.phone?`<div class="link-row"><a href="tel:${attr(i.phone.replace(/[^\d+]/g,""))}">📞 Asistencia: ${esc(i.phone)}</a></div>`:""}${drivePreview(i.documentUrl,i.insurer)}</div></details>`).join("")||'<div class="empty">Sin seguro de viaje</div>'}</div>`}
function checkItem(kind,x,extra=""){return`<div class="check-item ${x.done?"done":""}"><label><input type="checkbox" data-check="${kind}" data-id="${x.id}" ${x.done?"checked":""}><span>${esc(x.text)}</span>${extra}</label><button class="mini-btn" data-action="delete-${kind}" data-id="${x.id}" aria-label="Eliminar" title="Eliminar">✕</button></div>`}
function renderPacking(t){const cats=[...PACKING_CATS,...new Set(t.packing.map(x=>x.category).filter(c=>!PACKING_CATS.includes(c)))],done=t.packing.filter(x=>x.done).length;return`<div class="checklist">${t.packing.length?`<div class="meta"><strong>${done}/${t.packing.length} listos</strong></div>`:""}${cats.map(c=>{const items=t.packing.filter(x=>x.category===c);return items.length?`<div class="check-group"><div class="header-label">${esc(c)}</div>${items.map(x=>checkItem("packing",x)).join("")}</div>`:""}).join("")||'<div class="empty">Lista de equipaje vacía</div>'}<form data-form="packing-add" class="inline-add"><select name="category" aria-label="Categoría">${cats.map(c=>`<option ${c===(state.lastPackCat||PACKING_CATS[1])?"selected":""}>${esc(c)}</option>`).join("")}</select><input name="text" placeholder="Añadir elemento" aria-label="Elemento" required><button class="mini-btn" aria-label="Añadir">＋</button></form></div>`}
function renderTasks(t){const today=localISO(new Date()),list=[...t.tasks].sort((a,b)=>(a.done-b.done)||(a.dueDate||"9999").localeCompare(b.dueDate||"9999"));return`<div class="checklist">${list.map(x=>{const over=!x.done&&x.dueDate&&x.dueDate<today,isToday=!x.done&&x.dueDate===today;return checkItem("task",x,x.dueDate?`<small class="due ${over?"overdue":isToday?"today":""}">${over?"Vencida · ":isToday?"Hoy · ":""}${esc(shortDay(x.dueDate))}</small>`:"")}).join("")||'<div class="empty">Sin tareas ni recordatorios</div>'}<form data-form="task-add" class="inline-add"><input name="text" placeholder="Nueva tarea o recordatorio" aria-label="Tarea" required><input name="dueDate" type="date" aria-label="Fecha límite"><button class="mini-btn" aria-label="Añadir">＋</button></form></div>`}
function renderRates(t,b){const used=[...new Set([...t.activities.map(a=>a.currency||t.currency),...Object.keys(t.rates)].filter(c=>c&&c!=="EUR"))].sort();return`<form data-form="rates" class="rates-form"><div class="header-label">Tipos de cambio (fijos)</div>${used.map(c=>`<label class="rate-row"><span>1 ${esc(c)} =</span><input name="rate-${attr(c)}" type="number" min="0" step="0.0001" value="${attr(t.rates[c]??"")}"><span>€</span></label>`).join("")}<label class="rate-row"><span>Otra moneda</span><input name="newCurrency" maxlength="3" placeholder="USD" aria-label="Código de moneda"><input name="newRate" type="number" min="0" step="0.0001" placeholder="0,92" aria-label="Valor en euros"><span>€</span></label><button class="secondary-btn">Guardar tipos de cambio</button><p class="muted">El total del viaje siempre se muestra en euros.</p></form>`}
function renderPeopleBudget(t,b){if(!t.travelers.length)return'<p class="muted">Añade personas en «Personas» para ver el gasto de cada una.</p>';return`<div class="header-label">Por persona (reparto a partes iguales)</div><div class="compare-table-wrap"><table class="compare-table people-table"><thead><tr><th>Persona</th><th>Estimado</th><th>Gastado</th></tr></thead><tbody>${t.travelers.map(p=>{const x=b.byPerson[p.id]||{estimated:0,spent:0};return`<tr><th>${esc(p.name)}</th><td>${money(x.estimated,"EUR")}</td><td>${money(x.spent,"EUR")}</td></tr>`}).join("")}</tbody></table></div>`}
// ---- Calendario (.ics) ----
function icsText(s){return String(s??"").replace(/\\/g,"\\\\").replace(/;/g,"\\;").replace(/,/g,"\\,").replace(/\r?\n/g,"\\n")}
function foldICS(line){const enc=new TextEncoder();if(enc.encode(line).length<=75)return line;let out="",cur="",n=0;for(const ch of line){const b=enc.encode(ch).length;if(n+b>(out?74:75)){out+=(out?"\r\n ":"")+cur;cur="";n=0}cur+=ch;n+=b}return out+(out?"\r\n ":"")+cur}
function utcStamp(d){return d.toISOString().replace(/[-:]/g,"").replace(/\.\d{3}/,"")}
function buildICS(t){const tz=t.timeZone||"Europe/Madrid",now=utcStamp(new Date()),L=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//WanderLog//ES","CALSCALE:GREGORIAN","METHOD:PUBLISH",`X-WR-CALNAME:${icsText(t.name)}`];
 t.activities.forEach(a=>{const legs=[{v:legView(t,a,"ida"),uid:a.id,title:(a.returnTrip?"Ida · ":"")+a.title}];if(a.returnTrip)legs.push({v:legView(t,a,"vuelta"),uid:`${a.id}-vuelta`,title:`Vuelta · ${a.title}`});
  legs.forEach(({v,uid,title})=>{if(!v.date)return;L.push("BEGIN:VEVENT",`UID:${uid}@${t.id}.wanderlog`,`DTSTAMP:${now}`);if(v.time){const s=zonedToUTC(v.date,v.time,tz);let e=v.endTime?zonedToUTC(v.endDate||v.date,v.endTime,tz):new Date(s.getTime()+3600e3);if(e<=s)e=new Date(s.getTime()+3600e3);L.push(`DTSTART:${utcStamp(s)}`,`DTEND:${utcStamp(e)}`)}else L.push(`DTSTART;VALUE=DATE:${v.date.replace(/-/g,"")}`,`DTEND;VALUE=DATE:${addDays(v.endDate&&v.endDate>v.date?v.endDate:v.date,1).replace(/-/g,"")}`);
   L.push(`SUMMARY:${icsText(title)}`);if(v.location)L.push(`LOCATION:${icsText(v.location)}`);const desc=[a.status,a.locator&&`Localizador: ${a.locator}`,v.notes].filter(Boolean).join("\n");if(desc)L.push(`DESCRIPTION:${icsText(desc)}`);L.push("END:VEVENT")})});
 L.push("END:VCALENDAR");return L.map(foldICS).join("\r\n")+"\r\n"}
// ---- Impresión / PDF ----
function printSection(icon,title,body){return`<section class="print-section"><h2>${icon} ${esc(title)}</h2>${body}</section>`}
function renderPrint(t){const b=budget(t);return`<div class="print-view"><header class="print-head"><h1>${esc(t.icon)} ${esc(t.name)}</h1><p>${esc(t.destination)} · ${esc(formatTripRange(t.startDate,t.endDate))} · ${t.days.length} días${t.travelers.length?" · "+esc(travelerNames(t).join(", ")):""}</p></header>${renderTripHeader(t,b)}${printSection("🛏️","Alojamientos",renderAccommodations(t))}${printSection("🎟️","Reservas",renderReservations(t))}${printSection("🛡️","Seguro de viaje",renderInsurances(t))}${printSection("🧳","Equipaje",renderPacking(t))}${printSection("✅","Tareas y recordatorios",renderTasks(t))}${printSection("👥","Personas",renderTravelers(t))}${printSection("🧭","Práctico",renderPractical(t))}${printSection("🔗","Enlaces",renderLinks(t))}${printSection("📊","Gastos",renderBudgetBody(t))}
 ${t.days.map((d,i)=>{const s=stayForDay(t,d);return`<section class="print-day"><h2>Día ${i+1} · ${esc(formatDayDate(d.date))} · ${esc(d.name)}</h2>${weatherSlot(t,d)}<table class="print-table"><tbody>${dayEntries(t,d).map(({a,v})=>`<tr><td class="pt-time">${esc(timeLabel(v))}</td><td><strong>${CATEGORIES[a.category].icon} ${esc((a.returnTrip?(v.leg==="vuelta"?"Vuelta · ":"Ida · "):"")+a.title)}</strong> <span class="pt-status">${esc(a.status)}</span>${v.location?`<div>${esc(v.location)}</div>`:""}${a.locator?`<div>Localizador: ${esc(a.locator)}</div>`:""}${v.notes?`<div class="pt-notes">${nl2br(v.notes)}</div>`:""}</td></tr>`).join("")}${s?`<tr><td class="pt-time">Noche</td><td><strong>🛏️ ${esc(s.title)}</strong><div>${esc(s.location)}</div></td></tr>`:""}</tbody></table></section>`}).join("")}</div>`}
function printTrip(){let done=false;const finish=()=>{if(done)return;done=true;removeEventListener("afterprint",finish);state.printing=false;render()};state.printing=true;render();addEventListener("afterprint",finish);setTimeout(()=>{window.print();if(!("onafterprint"in window))setTimeout(finish,800)},400)}
function downloadFile(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement("a");a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function syncCatalog(){state.catalog=[...state.trips.values()].sort((a,b)=>(a.startDate||"").localeCompare(b.startDate||""))}
function applyRoute(){const m=location.hash.match(/^#viaje\/([^/?]+)/);if(m&&state.trips.has(decodeURIComponent(m[1]))){state.currentTripId=decodeURIComponent(m[1]);const p=new URLSearchParams(location.hash.split("?")[1]||"");state.view=["info","horario"].includes(p.get("vista"))?p.get("vista"):"info";state.printing=p.get("imprimir")==="1";const t=currentTrip();if(!t.days.some(d=>d.id===state.currentDayId))state.currentDayId=t.days[0]?.id||null}else state.currentTripId=null;state.modal=null;render()}
function render(){const printing=state.printing&&state.currentTripId;app.classList.toggle("printing",!!printing);if(printing){app.innerHTML=renderPrint(currentTrip());app.querySelectorAll("details").forEach(x=>x.open=true);return}app.innerHTML=`${state.online?"":'<div class="offline-banner">Sin conexión</div>'}${state.currentTripId?renderTrip():renderHome()}${renderModal()}`;scheduleLeafletMaps()}
function topbar(title="",sub=""){return `<header class="topbar"><div class="topbar-inner">${state.currentTripId?iconButton("home","←","Mis viajes"):`<a class="brand" href="#"><img class="brand-logo" src="assets/icons/icon.svg" alt=""><span>WanderLog</span></a>`}${state.currentTripId?`<div class="topbar-title"><strong>${esc(title)}</strong><small>${esc(sub)}</small></div>`:'<div style="flex:1"></div>'}${iconButton("settings","⚙️","Configuración")}</div></header>`}
function iconButton(action,icon,label,extra=""){return `<button class="icon-btn" data-action="${action}" ${extra} aria-label="${attr(label)}" title="${attr(label)}">${icon}</button>`}
function renderHome(){return `${topbar()}<main class="page"><div class="title-row"><h1>Mis viajes</h1></div><div class="icon-grid">${state.catalog.map(renderTripTile).join("")}<button class="trip-tile add-tile" data-action="new-trip"><span class="trip-icon">＋</span><span class="trip-name">Nuevo viaje</span></button></div></main>`}
function renderTripTile(t){return `<button class="trip-tile" data-action="open-trip" data-id="${attr(t.id)}"><span class="trip-icon">${esc(t.icon)}</span><span class="trip-name">${esc(t.name)}</span><span class="trip-date">${formatHomeRange(t.startDate,t.endDate)}</span></button>`}
function renderTrip(){const t=currentTrip(),people=peopleLabel(t);ensureTimeZone(t);return `${topbar(`${t.icon} ${t.name}`,`${formatTripRange(t.startDate,t.endDate)} · ${t.days.length} días${people?" · "+people:""}`)}<nav class="tabs">${mainTab("info","ℹ️ Info")}${mainTab("horario","🗓️ Horario")}</nav><main class="page">${state.view==="info"?renderInfo(t):renderSchedule(t)}</main>`}
function mainTab(view,label){return `<button data-action="set-view" data-view="${view}" class="${state.view===view?"active":""}">${label}</button>`}
function renderInfo(t){const b=budget(t);return `${renderTripHeader(t,b)}<div class="info-columns"><div>${infoSection("accommodations","🛏️","Alojamientos","add-accommodation",renderAccommodations(t))}${infoSection("reservations","🎟️","Reservas","add-reservation",renderReservations(t))}${infoSection("insurance","🛡️","Seguro de viaje","add-insurance",renderInsurances(t))}${infoSection("packing","🧳","Equipaje",null,renderPacking(t))}${infoSection("tasks","✅","Tareas y recordatorios",null,renderTasks(t))}</div><div>${infoSection("travelers","👥","Personas","add-traveler",renderTravelers(t))}${infoSection("practical","🧭","Práctico",null,renderPractical(t))}${infoSection("links","🔗","Enlaces","add-link",renderLinks(t))}</div></div>${infoSection("budget","📊","Gastos",null,renderBudgetBody(t))}<div class="print-actions"><button class="primary-btn" data-action="print-trip">🖨️ Guardar en PDF</button></div>`}
function infoSection(key,icon,title,addAction,body){const open=isInfoOpen(key);return `<section class="section info-section ${open?"":"collapsed"}"><div class="section-head"><button class="section-toggle" data-action="toggle-info-section" data-key="${key}" aria-expanded="${open}"><span>${icon}</span><h2>${title}</h2><span class="section-chevron">${open?"⌃":"⌄"}</span></button>${addAction?`<button class="mini-btn" data-action="${addAction}" aria-label="Añadir ${attr(title.toLowerCase())}" title="Añadir ${attr(title.toLowerCase())}">＋</button>`:""}</div><div class="section-body">${body}</div></section>`}
function isInfoOpen(key){const id=state.currentTripId||"global",saved=state.settings.infoSections?.[id]?.[key];return saved===undefined?true:!!saved}
function setInfoOpen(key,open){state.settings.infoSections||={};state.settings.infoSections[state.currentTripId]||={};state.settings.infoSections[state.currentTripId][key]=open;localStorage.setItem(SETTINGS_KEY,JSON.stringify(state.settings))}
function renderAccommodations(t){return `<div class="compact-list">${stays(t).map(a=>{const place=a.mapQuery||a.location;return `<article class="compact-card"><div class="compact-card-head"><span>🛏️</span><strong>${esc(a.title)}</strong><button class="mini-btn" data-action="edit-activity" data-id="${a.id}" aria-label="Editar" title="Editar">✏️</button></div><p>${esc(a.location)}</p><div class="meta"><span>${esc(stayLabel(t,a))}</span></div><div class="meta"><span class="badge ${slug(a.status)}">${esc(a.status)}</span><span>${amount(t,a,a.spent)}</span></div><div class="link-row">${place?`<a href="${mapSearch(stripMapUrl(place))}" target="_blank" rel="noopener">📍 Mapa</a>`:""}</div>${a.bookingUrl?`<details class="doc-details"><summary>📄 Documento de la reserva</summary>${drivePreview(a.bookingUrl,a.title)}</details>`:""}</article>`}).join("")||'<div class="empty">Sin alojamientos</div>'}</div>`}
function renderReservations(t){return `<div class="compact-list">${t.activities.filter(isBooking).map(a=>{const ida=legView(t,a,"ida"),place=a.mapQuery||a.location,included=t.activities.filter(x=>x.linkedTo===a.id).map(x=>x.title),lines=[isStay(t,a)?stayLabel(t,a):`${a.returnTrip?"Ida: ":""}${rangeLabel(ida)}`,a.returnTrip&&`Vuelta: ${rangeLabel(legView(t,a,"vuelta"))}`,a.locator&&`Localizador: ${a.locator}`,a.location,a.notes,a.returnTrip?.notes&&`Notas para la vuelta: ${a.returnTrip.notes}`,included.length&&`Incluye: ${included.join(", ")}`];return `<details class="details-block"><summary><span>${CATEGORIES[a.category].icon} ${esc(a.title)}</span><span class="badge ${slug(a.status)}">${esc(a.status)}</span><button class="mini-btn" data-action="edit-activity" data-id="${a.id}" aria-label="Editar" title="Editar">✏️</button></summary><div class="details-content">${esc(lines.filter(Boolean).join("\n"))}${drivePreview(a.bookingUrl,a.title)}<div class="money-pair"><span>Estimado ${amount(t,a,a.estimated)}</span><span>Gastado ${amount(t,a,a.spent)}</span></div><div class="link-row">${place?`<a href="${mapSearch(stripMapUrl(place))}" target="_blank" rel="noopener">📍 Mapa</a>`:""}${linksHtml(a)}</div></div></details>`}).join("")||'<div class="empty">Sin reservas</div>'}</div>`}
function renderPractical(t){return PRACTICAL.map(k=>`<details class="details-block"><summary><span>${practicalIcon(k)} ${titleCase(k)}</span><button class="mini-btn" data-action="edit-practical" data-key="${attr(k)}" aria-label="Editar" title="Editar">✏️</button></summary><div class="details-content">${esc(t.practical[k]||"Sin notas")}</div></details>`).join("")}
function renderLinks(t){return `<div class="compact-list">${t.links.map(l=>`<div class="compact-card"><div class="compact-card-head"><span>🔗</span><strong>${esc(l.label)}</strong><a href="${safeUrl(l.url)}" target="_blank" rel="noopener" aria-label="Abrir">↗</a><button class="mini-btn" data-action="edit-link" data-id="${l.id||""}" data-index="${t.links.indexOf(l)}" aria-label="Editar">✏️</button></div></div>`).join("")||'<div class="empty">Sin enlaces</div>'}</div>`}
function renderBudgetBody(t){const b=budget(t),max=Math.max(1,...Object.values(b.byCategory).map(x=>x.spent)),totalMax=Math.max(1,b.estimated,b.spent);return `${b.missing.length?`<div class="warn">⚠️ Falta el tipo de cambio de ${esc(b.missing.join(", "))}. Esos importes no se suman al total.</div>`:""}<div class="compare"><div><span>Estimado</span><strong>${money(b.estimated,"EUR")}</strong><div class="bar-track"><div class="bar-fill" style="width:${Math.round(b.estimated/totalMax*100)}%"></div></div></div><div><span>Gastado</span><strong>${money(b.spent,"EUR")}</strong><div class="bar-track"><div class="bar-fill" style="width:${Math.round(b.spent/totalMax*100)}%;background:#f0a74b"></div></div></div></div><div class="budget-bars">${Object.entries(b.byCategory).map(([cat,x])=>`<div class="bar-row"><span>${CATEGORIES[cat].icon} ${esc(cat)}</span><div class="bar-track"><div class="bar-fill category-${CATEGORIES[cat].className}" style="width:${Math.round(x.spent/max*100)}%;background:var(--cat)"></div></div><strong>${money(x.spent,"EUR")}</strong></div>`).join("")}</div><div class="budget-people">${renderPeopleBudget(t,b)}</div><div class="compact-list" style="margin-top:9px">${t.days.map(d=>{const x=b.byDay[d.id]||{estimated:0,spent:0};return `<div class="compact-card"><div class="compact-card-head"><strong>${formatDayDate(d.date)} · ${esc(d.name)}</strong><span>${money(x.spent,"EUR")}</span></div><div class="meta">Estimado ${money(x.estimated,"EUR")}</div></div>`}).join("")}</div>${renderRates(t,b)}`}
function renderSchedule(t){const d=currentDay(t);if(!d)return '<div class="empty">Sin días</div>';return `<div class="day-tabs">${t.days.map((x,i)=>`<button class="day-tab ${x.id===d.id?"active":""}" data-action="select-day" data-id="${x.id}"><strong>Día ${i+1}</strong><span>${shortDay(x.date)}</span></button>`).join("")}<button class="day-tab add" data-action="add-day" aria-label="Añadir día">＋</button></div><div class="day-bar"><div><h2>${esc(d.name)}</h2><small>${formatDayDate(d.date)}</small></div><div class="view-toggle"><button data-action="day-view" data-view="plan" class="${state.dayView==="plan"?"active":""}">Plan</button><button data-action="day-view" data-view="mapa" class="${state.dayView==="mapa"?"active":""}">Mapa</button></div>${iconButton("edit-day","✏️","Editar día",`data-id="${d.id}"`)}</div>${weatherSlot(t,d)}${staySwitch(t,d)}${state.dayView==="plan"?renderDayPlan(t,d):renderDayMap(t,d)}`}
function renderDayPlan(t,d){return `<div class="activities">${dayEntries(t,d).map(x=>renderActivity(t,d,x.a,x.v)).join("")}${renderLodgingActivity(t,d)}</div><div style="display:flex;justify-content:center;margin:9px"><button class="primary-btn" data-action="add-activity" data-day-id="${d.id}">＋ Actividad</button></div>`}
function renderActivity(t,d,a,v=legView(t,a,"ida")){const c=CATEGORIES[a.category],open=state.expanded.has(v.key),acc=activeStay(t,d,v.time),accPlace=acc&&(acc.mapQuery||acc.location),place=v.mapQuery||v.location,isReturn=v.leg==="vuelta",prefix=a.returnTrip?(isReturn?"Vuelta · ":"Ida · "):"",parent=a.linkedTo&&t.activities.find(x=>x.id===a.linkedTo),legAttr=isReturn?' data-leg="vuelta"':"";return `<article class="activity category-${c.className} ${v.completed?"completed":""} ${open?"expanded":""}"><div class="activity-line"><button class="check" data-action="toggle-complete" data-id="${a.id}"${legAttr} aria-label="Completar">${v.completed?"✓":""}</button><span class="cat-icon">${c.icon}</span><button class="activity-main" data-action="toggle-activity" data-id="${v.key}"><span><span class="activity-time">${esc(timeLabel(v))}</span><span class="activity-title">${esc(prefix+a.title)}</span></span></button><span class="activity-right"><span class="badge activity-status ${slug(a.status)}">${esc(a.status)}</span><span class="spent-inline">${!isReturn&&a.spent?money(a.spent,a.currency||t.currency):""}</span></span></div><div class="activity-detail"><div class="meta"><span>${esc(v.location||"")}</span>${a.locator?`<span>· Localizador: ${esc(a.locator)}</span>`:""}</div>${parent?`<div class="meta"><span>Incluida en: ${esc(parent.title)}</span></div>`:""}${v.notes?`<p>${nl2br(v.notes)}</p>`:""}${place?miniMap(place,a.title,v.lat,v.lng):""}${isReturn?"":`<div class="money-pair"><span>Estimado ${amount(t,a,a.estimated)}</span><span>Gastado ${amount(t,a,a.spent)}</span></div>`}<div class="link-row">${directionsButton(place,"Cómo llegar")}${accPlace&&acc.id!==a.id?directionsButton(accPlace,"Volver al alojamiento",place):""}${docButton(a)}${linksHtml(a)}<button data-action="edit-activity" data-id="${a.id}">✏️ Editar</button></div></div></article>`}
function renderLodgingActivity(t,d){const a=shownStay(t,d),id=`lodging-${d.id}`,open=state.expanded.has(id),leaving=a&&a.endDate===d.date;if(!a){if(d.id===t.days.at(-1)?.id)return"";return `<article class="activity category-alojamiento ${open?"expanded":""}"><div class="activity-line lodging-line"><span></span><span class="cat-icon">🛏️</span><button class="activity-main" data-action="toggle-activity" data-id="${id}"><span><span class="activity-time">Final</span><span class="activity-title">Sin alojamiento</span></span></button><span class="activity-right"><span class="badge activity-status pendiente">Pendiente</span></span></div><div class="activity-detail"><div class="link-row"><button data-action="add-stay" data-day-id="${d.id}">＋ Añadir alojamiento</button></div></div></article>`}const place=a.mapQuery||a.location;return `<article class="activity category-alojamiento special-lodging ${open?"expanded":""}"><div class="activity-line lodging-line"><span></span><span class="cat-icon">🛏️</span><button class="activity-main" data-action="toggle-activity" data-id="${id}"><span><span class="activity-time">${leaving?`Salida ${esc(a.endTime||"")}`:"Final"}</span><span class="activity-title">${leaving?"Salida · ":""}${esc(a.title)}</span></span></button><span class="activity-right"><span class="badge activity-status ${slug(a.status)}">${esc(a.status)}</span><span class="spent-inline">${a.spent?money(a.spent,a.currency||t.currency):""}</span></span></div><div class="activity-detail"><div class="meta"><span>${esc(a.location)}</span></div><div class="meta"><span>${esc(stayLabel(t,a))}</span>${a.locator?`<span>· Localizador: ${esc(a.locator)}</span>`:""}</div>${a.notes?`<p>${nl2br(a.notes)}</p>`:""}${place?miniMap(place,a.title,a.lat,a.lng):""}<div class="money-pair"><span>Estimado ${amount(t,a,a.estimated)}</span><span>Gastado ${amount(t,a,a.spent)}</span></div><div class="link-row">${directionsButton(place,"Cómo llegar")}${docButton(a)}${linksHtml(a)}<button data-action="edit-activity" data-id="${a.id}">✏️ Editar alojamiento</button></div></div></article>`}
function miniMap(place,title,lat,lng){return `<div class="mini-map leaflet-map" role="img" aria-label="Mapa de ${attr(title)}" data-map-kind="mini" data-place="${attr(stripMapUrl(place))}" data-lat="${Number.isFinite(+lat)?+lat:""}" data-lng="${Number.isFinite(+lng)?+lng:""}"></div>`}
function renderDayMap(t,d){const acc=shownStay(t,d),stops=[...dayEntries(t,d).map(({a,v})=>({title:(a.returnTrip?(v.leg==="vuelta"?"Vuelta · ":"Ida · "):"")+a.title,place:v.mapQuery||v.location,lat:v.lat,lng:v.lng})),...(acc?[{title:acc.title,place:acc.mapQuery||acc.location,lat:acc.lat,lng:acc.lng}]:[])].filter(x=>x.place);if(!stops.length)return '<div class="empty">Sin ubicaciones para crear la ruta</div>';return `<div class="day-route-map leaflet-map" role="img" aria-label="Ruta completa de ${attr(d.name)}" data-map-kind="route" data-stops="${attr(JSON.stringify(stops))}"></div><div class="route-actions"><a href="${routeUrl(stops.map(x=>x.place))}" target="_blank" rel="noopener">Abrir ruta en Google Maps</a></div>`}
function scheduleLeafletMaps(){if(typeof window==="undefined"||typeof document==="undefined")return;const run=()=>initLeafletMaps().catch(error=>console.warn("Mapas Leaflet",error));if(typeof requestAnimationFrame==="function")requestAnimationFrame(run);else setTimeout(run,0)}
async function initLeafletMaps(){if(typeof L==="undefined")return;const nodes=[...document.querySelectorAll(".leaflet-map:not([data-map-ready])")].filter(node=>node.offsetParent!==null);for(const node of nodes){node.dataset.mapReady="true";try{if(node.dataset.mapKind==="mini")await initMiniLeafletMap(node);else await initRouteLeafletMap(node)}catch(error){node.dataset.mapReady="error";node.innerHTML='<div class="map-error">Mapa no disponible</div>';console.warn(error)}}}
function leafletBase(node,zoomControl=true){const map=L.map(node,{zoomControl,attributionControl:true,scrollWheelZoom:false,dragging:true,tap:false});L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);return map}
async function initMiniLeafletMap(node){const lat=+node.dataset.lat,lng=+node.dataset.lng,coords=Number.isFinite(lat)&&Number.isFinite(lng)&&lat&&lng?[lat,lng]:await geocodePlace(node.dataset.place);if(!coords)throw Error("Ubicación no encontrada");const map=leafletBase(node,false);map.setView(coords,15);L.circleMarker(coords,{radius:7,color:"#fff",weight:2,fillColor:"#176b5b",fillOpacity:1}).addTo(map);setTimeout(()=>map.invalidateSize(),0)}
async function initRouteLeafletMap(node){const raw=JSON.parse(node.dataset.stops||"[]"),stops=[];for(const stop of raw){let coords=Number.isFinite(+stop.lat)&&Number.isFinite(+stop.lng)&&+stop.lat&&+stop.lng?[+stop.lat,+stop.lng]:await geocodePlace(stripMapUrl(stop.place));if(coords)stops.push({...stop,coords})}if(!stops.length)throw Error("Ruta sin ubicaciones");const map=leafletBase(node,true),line=stops.map(x=>x.coords);if(line.length>1)L.polyline(line,{color:"#176b5b",weight:4,opacity:.82}).addTo(map);stops.forEach((stop,i)=>L.marker(stop.coords,{icon:numberedLeafletIcon(i+1)}).addTo(map).bindPopup(`<strong>${esc(stop.title)}</strong>`));line.length===1?map.setView(line[0],15):map.fitBounds(line,{padding:[28,28],maxZoom:15});setTimeout(()=>map.invalidateSize(),0)}
function numberedLeafletIcon(number){return L.divIcon({className:"numbered-leaflet-icon",html:`<span>${number}</span>`,iconSize:[28,28],iconAnchor:[14,14],popupAnchor:[0,-15]})}
let geocodeQueue=Promise.resolve();function geocodePlace(place){const query=String(place||"").trim(),key=`wanderlog.geo.${query.toLowerCase()}`,cached=loadJSON(key,null);if(Array.isArray(cached)&&cached.length===2)return Promise.resolve(cached);const task=async()=>{const url=`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q=${encodeURIComponent(query)}`;const response=await fetch(url,{headers:{Accept:"application/json"}});if(!response.ok)return null;const data=await response.json(),coords=data[0]?[+data[0].lat,+data[0].lon]:null;if(coords)localStorage.setItem(key,JSON.stringify(coords));await new Promise(resolve=>setTimeout(resolve,300));return coords};geocodeQueue=geocodeQueue.then(task,task);return geocodeQueue}
function renderModal(){if(!state.modal)return"";const m=state.modal;if(m.type==="new-trip")return newTripModal();if(m.type==="activity")return activityModal(m.id,m.dayId,m.preset);if(m.type==="day")return dayModal(m.id,m.isNew);if(m.type==="trip")return tripModal();if(m.type==="practical")return practicalModal(m.key);if(m.type==="link")return linkModal(m.index);if(m.type==="settings")return settingsModal();if(m.type==="import-conflict")return importConflictModal(m.trip);if(m.type==="import-new")return importNewModal(m.trip);if(m.type==="traveler")return travelerModal(m.id);if(m.type==="insurance")return insuranceModal(m.id);return""}
function modal(title,body){return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" data-modal-body role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2>${iconButton("close-modal","×","Cerrar")}</div>${body}</section></div>`}
function newTripModal(){const today=localISO(new Date());return modal("Nuevo viaje",`<form data-form="new-trip" class="form-grid cols-2">${field("Nombre","name","text","",true)}${field("Destino","destination","text","",true)}${field("Inicio","startDate","date",today,true)}${field("Fin","endDate","date",today,true)}<div class="span-2 btn-row"><button class="secondary-btn" type="button" data-action="close-modal">Cancelar</button><button class="primary-btn">Crear</button></div></form>`)}
function activityModal(id,dayId,preset){const t=currentTrip(),day=dayId||state.currentDayId||t.days[0]?.id,start=dayDate(t,day),isNewStay=preset==="stay",a=t.activities.find(x=>x.id===id)||{id:"",dayId:day,time:isNewStay?"15:00":"09:00",endDate:isNewStay?addDays(start,1):start,endTime:isNewStay?"11:00":"",title:"",category:isNewStay?"Alojamiento":"Otro",location:"",mapQuery:"",status:preset==="booking"?"Reservado":"Pendiente",completed:false,notes:"",locator:"",bookingUrl:"",links:[],estimated:0,spent:0,linkedTo:null,returnTrip:null},tr=a.category==="Transporte",hasR=tr&&!!a.returnTrip,mode=a.category==="Alojamiento"?1:hasR?2:0,r=a.returnTrip||{dayId:a.dayId,time:"",endDate:"",endTime:"",notes:"",location:"",mapQuery:""},days=t.days.map(d=>[d.id,`${formatDayDate(d.date)} · ${d.name}`]),parents=t.activities.filter(x=>x.id!==a.id&&isBooking(x)).map(x=>[x.id,x.title]),hide=c=>c?"":' style="display:none"';return modal(a.id?"Editar actividad":(a.category==="Alojamiento"?"Nuevo alojamiento":"Nueva actividad"),`<form data-form="activity" class="form-grid cols-2"><input type="hidden" name="id" value="${attr(a.id)}"><div class="span-2">${field("Título","title","text",a.title,true)}</div>${selectField("Categoría","category",Object.keys(CATEGORIES).map(x=>[x,x]),a.category)}${selectField("Estado","status",STATUSES.map(x=>[x,x]),a.status)}${modeSelect("Día|Día de check-in|Día de la ida","dayId",days,a.dayId,mode)}${modeField("Hora inicio|Hora de check-in|Hora inicio ida","time","time",a.time,mode)}${modeField("Fecha fin|Fecha de check-out|Fecha fin ida","endDate","date",a.endDate,mode)}${modeField("Hora fin|Hora de check-out|Hora fin ida","endTime","time",a.endTime,mode)}${field("Ubicación","location","text",a.location)}${field("Búsqueda de mapa","mapQuery","text",a.mapQuery)}<div class="field span-2"><label data-labels="Notas|Notas|Notas para la ida">${["Notas","Notas","Notas para la ida"][mode]}</label><textarea name="notes">${esc(a.notes)}</textarea></div><div class="span-2 form-grid cols-2" data-only="Transporte"${hide(tr)}><div class="span-2">${selectField("¿Tiene vuelta?","hasReturn",[["no","No"],["si","Sí"]],hasR?"si":"no")}</div><div class="span-2 form-grid cols-2" data-return${hide(hasR)}>${selectField("Día de la vuelta","returnDayId",days,r.dayId).replace("<select",`<select data-prev="${attr(r.dayId)}"`)}${field("Hora inicio vuelta","returnTime","time",r.time)}${field("Fecha fin vuelta","returnEndDate","date",r.endDate)}${field("Hora fin vuelta","returnEndTime","time",r.endTime)}${field("Ubicación de la vuelta","returnLocation","text",r.location)}${field("Búsqueda de mapa vuelta","returnMapQuery","text",r.mapQuery)}<div class="field span-2"><label>Notas para la vuelta</label><textarea name="returnNotes">${esc(r.notes)}</textarea></div></div></div>${field("Localizador","locator","text",a.locator)}${field("Documento de reserva (Drive)","bookingUrl","url",a.bookingUrl)}${field("Estimado","estimated","number",a.estimated)}${field("Gastado","spent","number",a.spent)}${field("Moneda (código de 3 letras)","currency","text",a.currency||t.currency)}${t.travelers.length?`<div class="field span-2"><label>Participantes (el gasto se reparte a partes iguales)</label><div class="check-list">${t.travelers.map(p=>`<label><input type="checkbox" name="participants" value="${attr(p.id)}" ${!a.participants?.length||a.participants.includes(p.id)?"checked":""}> ${esc(p.name)}</label>`).join("")}</div></div>`:""}${selectField("Incluida en","linkedTo",[["","Ninguna"],...parents],a.linkedTo||"")}<div class="field"><label>Completada</label><select name="completed"><option value="false" ${!a.completed?"selected":""}>No</option><option value="true" ${a.completed?"selected":""}>Sí</option></select></div><div class="field span-2"><label>Enlaces relevantes (etiqueta|URL, uno por línea)</label><textarea name="links">${esc(a.links.map(l=>`${l.label}|${l.url}`).join("\n"))}</textarea></div><div class="span-2 btn-row">${a.id?'<button type="button" class="danger-btn" data-action="delete-activity" data-id="'+a.id+'">🗑️</button>':""}<button class="primary-btn">Guardar</button></div></form>`)}
function dayModal(id,isNew=false){const t=currentTrip(),d=t.days.find(x=>x.id===id)||{id:"",date:nextDayDate(t),name:`Día ${t.days.length+1}`},acts=t.activities.filter(a=>a.dayId===d.id);return modal(isNew?"Añadir día":"Editar día",`<form data-form="day" class="form-grid"><input type="hidden" name="id" value="${attr(d.id)}">${field("Fecha","date","date",d.date,true)}${field("Nombre resumen","name","text",d.name,true)}${d.id?`<div class="edit-rows">${acts.map(a=>editActivityRow(t,a)).join("")||'<div class="empty">Sin actividades</div>'}</div><button type="button" class="secondary-btn" data-action="add-activity" data-day-id="${d.id}">＋ Actividad</button>`:""}<div class="btn-row">${d.id?`<button type="button" class="danger-btn" data-action="delete-day" data-id="${d.id}">🗑️ Día</button>`:""}<button class="primary-btn">Guardar</button></div></form>`)}
function editActivityRow(t,a){return `<div class="edit-row" data-row-id="${a.id}"><div class="edit-row-grid"><input name="time" type="time" value="${attr(a.time)}"><input name="title" value="${attr(a.title)}"><select name="dayId">${t.days.map(d=>`<option value="${d.id}" ${d.id===a.dayId?"selected":""}>${shortDay(d.date)}</option>`).join("")}</select><select name="status">${STATUSES.map(s=>`<option ${s===a.status?"selected":""}>${s}</option>`).join("")}</select></div><div class="row-actions"><button type="button" class="mini-btn" data-action="edit-activity" data-id="${a.id}" title="Editar">✏️</button><button type="button" class="mini-btn" data-action="duplicate-activity" data-id="${a.id}" title="Duplicar">⧉</button><button type="button" class="mini-btn" data-action="delete-activity" data-id="${a.id}" title="Eliminar">🗑️</button></div></div>`}
function tripModal(){const t=currentTrip();return modal("Editar viaje",`<form data-form="trip" class="form-grid cols-2">${field("Nombre","name","text",t.name,true)}${field("Destino","destination","text",t.destination,true)}${field("Inicio","startDate","date",t.startDate,true)}${field("Fin","endDate","date",t.endDate,true)}${field("Icono","icon","text",t.icon,true)}${field("Moneda habitual de los gastos","currency","text",t.currency,true)}<div class="span-2">${field("Zona horaria del destino (p. ej. Europe/Athens; vacío = detectar)","timeZone","text",t.timeZone)}</div><p class="span-2 muted">Al cambiar las fechas se añaden o eliminan días en Horario. Si se eliminan días con actividades, se pedirá confirmación.</p><div class="span-2 btn-row"><button class="primary-btn">Guardar</button></div></form>`)}
function travelerModal(id){const p=currentTrip().travelers.find(x=>x.id===id)||{id:"",name:""};return modal(p.id?"Editar persona":"Nueva persona",`<form data-form="traveler" class="form-grid"><input type="hidden" name="id" value="${attr(p.id)}">${field("Nombre","name","text",p.name,true)}<div class="btn-row">${p.id?`<button type="button" class="danger-btn" data-action="delete-traveler" data-id="${p.id}">🗑️</button>`:""}<button class="primary-btn">Guardar</button></div></form>`)}
function insuranceModal(id){const t=currentTrip(),i=t.insurances.find(x=>x.id===id)||{id:"",insurer:"",policyNumber:"",phone:"",startDate:t.startDate,endDate:t.endDate,documentUrl:"",notes:""};return modal(i.id?"Editar seguro":"Nuevo seguro de viaje",`<form data-form="insurance" class="form-grid cols-2"><input type="hidden" name="id" value="${attr(i.id)}"><div class="span-2">${field("Aseguradora","insurer","text",i.insurer,true)}</div>${field("Número de póliza","policyNumber","text",i.policyNumber)}${field("Teléfono de asistencia","phone","tel",i.phone)}${field("Cobertura desde","startDate","date",i.startDate)}${field("Cobertura hasta","endDate","date",i.endDate)}<div class="span-2">${field("Documento de la póliza (Drive)","documentUrl","url",i.documentUrl)}</div><div class="field span-2"><label>Notas</label><textarea name="notes">${esc(i.notes)}</textarea></div><div class="span-2 btn-row">${i.id?`<button type="button" class="danger-btn" data-action="delete-insurance" data-id="${i.id}">🗑️</button>`:""}<button class="primary-btn">Guardar</button></div></form>`)}
function practicalModal(key){return modal(titleCase(key),`<form data-form="practical" class="form-grid"><input type="hidden" name="key" value="${attr(key)}"><div class="field"><label>Notas</label><textarea name="value">${esc(currentTrip().practical[key])}</textarea></div><button class="primary-btn">Guardar</button></form>`)}
function linkModal(index){const l=currentTrip().links[index]||{label:"",url:""};return modal(index>=0?"Editar enlace":"Nuevo enlace",`<form data-form="link" class="form-grid"><input type="hidden" name="index" value="${index}">${field("Nombre","label","text",l.label,true)}${field("URL","url","url",l.url,true)}<div class="btn-row">${index>=0?`<button type="button" class="danger-btn" data-action="delete-link" data-index="${index}">🗑️</button>`:""}<button class="primary-btn">Guardar</button></div></form>`)}
function settingsModal(){const t=currentTrip();return modal("Ajustes",`<div class="settings-list"><div class="setting"><h3>Copia del viaje</h3><p>${t?"Descarga este viaje en un archivo .json o abre uno que hayas exportado antes. Los cambios ya se guardan solos en este dispositivo.":"Abre un archivo .json que hayas exportado antes. Para exportar, abre primero un viaje."}</p><div class="btn-row">${t?'<button class="secondary-btn" data-action="export-trip">⬇️ Exportar viaje</button>':""}<button class="secondary-btn" data-action="import">⬆️ Importar viaje</button>${t?'<button class="secondary-btn" data-action="export-ics">📅 Exportar a calendario (.ics)</button>':""}</div></div><div class="setting"><h3>Moneda para viajes nuevos</h3><form data-form="default-currency" class="btn-row"><input aria-label="Código de moneda" name="currency" maxlength="3" value="${attr(state.settings.defaultCurrency)}"><button class="primary-btn">Guardar moneda</button></form></div>${t?'<div class="setting"><h3>Gestionar este viaje</h3><div class="btn-row"><button class="secondary-btn" data-action="edit-trip">✏️ Editar nombre, destino e icono</button>'+(state.published.has(t.id)?'<button class="danger-btn" data-action="restore-published">↺ Restaurar este viaje</button>':"")+'<button class="danger-btn" data-action="delete-trip">🗑️ Eliminar este viaje</button></div></div>':""}<div class="setting"><h3>Instalar WanderLog ${APP_VERSION}</h3><p>Instala la aplicación para abrirla desde la pantalla de inicio y usar la caché sin conexión.</p>${state.deferredInstall?'<button class="primary-btn" data-action="install">⬇️ Instalar WanderLog</button>':'<p>Usa la opción “Añadir a pantalla de inicio” del navegador.</p>'}</div></div>`)}
function field(label,name,type,value,required=false){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${attr(value??"")}" ${required?"required":""} ${type==="number"?'min="0" step="0.01"':""}></div>`}
function selectField(label,name,options,value){return `<div class="field"><label>${label}</label><select name="${name}">${options.map(([v,l])=>`<option value="${attr(v)}" ${v===value?"selected":""}>${esc(l)}</option>`).join("")}</select></div>`}
function modeLabel(labels,mode){return `<label data-labels="${attr(labels)}">${esc(labels.split("|")[mode])}</label>`}
function modeField(labels,name,type,value,mode){return field("",name,type,value).replace("<label></label>",modeLabel(labels,mode))}
function modeSelect(labels,name,options,value,mode){return selectField("",name,options,value).replace("<label></label>",modeLabel(labels,mode)).replace("<select",`<select data-prev="${attr(value)}"`)}
function updateActivityForm(f,changed){const e=f.elements,t=currentTrip(),cat=e.namedItem("category").value,hasR=cat==="Transporte"&&e.namedItem("hasReturn").value==="si",mode=cat==="Alojamiento"?1:hasR?2:0,isNew=!e.namedItem("id").value;f.querySelectorAll("[data-only]").forEach(el=>el.style.display=el.dataset.only===cat?"":"none");f.querySelectorAll("[data-return]").forEach(el=>el.style.display=hasR?"":"none");f.querySelectorAll("label[data-labels]").forEach(l=>l.textContent=l.dataset.labels.split("|")[mode]);
 const sync=(sel,endName)=>{const prev=dayDate(t,sel.dataset.prev),now=dayDate(t,sel.value),end=e.namedItem(endName);if(!end.value||end.value===prev||end.value<now)end.value=cat==="Alojamiento"&&sel.name==="dayId"?addDays(now,1):now;sel.dataset.prev=sel.value};
 if(changed==="dayId")sync(e.namedItem("dayId"),"endDate");if(changed==="returnDayId")sync(e.namedItem("returnDayId"),"returnEndDate");
 if(changed==="category"&&cat==="Alojamiento"&&isNew){const start=dayDate(t,e.namedItem("dayId").value);if(!e.namedItem("time").value||e.namedItem("time").value==="09:00")e.namedItem("time").value="15:00";if(!e.namedItem("endTime").value)e.namedItem("endTime").value="11:00";if(!e.namedItem("endDate").value||e.namedItem("endDate").value<=start)e.namedItem("endDate").value=addDays(start,1)}else if(changed==="category"&&isNew){const start=dayDate(t,e.namedItem("dayId").value);if(e.namedItem("endDate").value===addDays(start,1))e.namedItem("endDate").value=start;if(e.namedItem("time").value==="15:00"&&e.namedItem("endTime").value==="11:00"){e.namedItem("time").value="09:00";e.namedItem("endTime").value=""}}
 if(changed==="hasReturn"&&hasR&&!e.namedItem("returnEndDate").value)e.namedItem("returnEndDate").value=dayDate(t,e.namedItem("returnDayId").value)}
function handleClick(e){const x=e.target.closest("[data-action]");if(!x)return;const a=x.dataset.action;if(a==="close-modal"&&e.target.closest("[data-modal-body]")&&!e.target.closest("button[data-action='close-modal']"))return;
 if(a==="toggle-info-section"){const open=!isInfoOpen(x.dataset.key);setInfoOpen(x.dataset.key,open);render()}else if(a==="home")location.hash="";else if(a==="open-trip")location.hash=`#viaje/${encodeURIComponent(x.dataset.id)}?vista=info`;else if(a==="set-view"){state.view=x.dataset.view;location.hash=`#viaje/${encodeURIComponent(state.currentTripId)}?vista=${state.view}`;render()}else if(a==="settings")openModal("settings");else if(a==="close-modal"||a==="import-cancel"){if(["import-conflict","import-new"].includes(state.modal?.type))nextImport();else{state.modal=null;render()}}else if(a==="import-replace"){storeImported(state.modal.trip);nextImport()}else if(a==="import-as-new")openModal("import-new",{trip:state.modal.trip});else if(a==="import-back")openModal("import-conflict",{trip:state.modal.trip});else if(a==="add-traveler")openModal("traveler");else if(a==="edit-traveler")openModal("traveler",{id:x.dataset.id});else if(a==="delete-traveler")deleteTraveler(x.dataset.id);else if(a==="add-insurance")openModal("insurance");else if(a==="edit-insurance")openModal("insurance",{id:x.dataset.id});else if(a==="delete-insurance"){if(!confirm("¿Eliminar este seguro?"))return;const t=currentTrip();t.insurances=t.insurances.filter(i=>i.id!==x.dataset.id);finishSave("Seguro eliminado")}else if(a==="delete-packing"||a==="delete-task"){const t=currentTrip(),k=a==="delete-packing"?"packing":"tasks";t[k]=t[k].filter(i=>i.id!==x.dataset.id);saveCurrent();render()}else if(a==="go-day"){state.currentDayId=x.dataset.id;state.view="horario";state.dayView="plan";location.hash=`#viaje/${encodeURIComponent(state.currentTripId)}?vista=horario`;render()}else if(a==="stay-choice"){state.stayChoice[x.dataset.dayId]=+x.dataset.idx;render()}else if(a==="export-ics"){const t=currentTrip();downloadFile(buildICS(t),`${slug(t.name)}.ics`,"text/calendar;charset=utf-8");toast("Calendario exportado")}else if(a==="print-trip")printTrip();else if(a==="new-trip")openModal("new-trip");else if(a==="edit-trip")openModal("trip");else if(a==="select-day"){state.currentDayId=x.dataset.id;state.dayView="plan";render()}else if(a==="day-view"){state.dayView=x.dataset.view;render()}else if(a==="add-day")openModal("day",{isNew:true});else if(a==="edit-day")openModal("day",{id:x.dataset.id});else if(a==="add-stay")openModal("activity",{preset:"stay",dayId:x.dataset.dayId});else if(a==="add-activity")openModal("activity",{dayId:x.dataset.dayId||state.currentDayId});else if(a==="edit-activity")openModal("activity",{id:x.dataset.id});else if(a==="toggle-activity"){state.expanded.has(x.dataset.id)?state.expanded.delete(x.dataset.id):state.expanded.add(x.dataset.id);render()}else if(a==="toggle-complete"){const y=findActivity(x.dataset.id);if(!y)return;if(x.dataset.leg==="vuelta"&&y.returnTrip){y.returnTrip.completed=!y.returnTrip.completed;state.expanded.delete(`${y.id}::vuelta`)}else{y.completed=!y.completed;state.expanded.delete(y.id)}saveCurrent();render()}else if(a==="duplicate-activity")duplicateActivity(x.dataset.id);else if(a==="delete-activity")deleteActivity(x.dataset.id);else if(a==="delete-day")deleteDay(x.dataset.id);else if(a==="add-accommodation")openModal("activity",{preset:"stay"});else if(a==="add-reservation")openModal("activity",{preset:"booking"});else if(a==="edit-practical")openModal("practical",{key:x.dataset.key});else if(a==="add-link")openModal("link",{index:-1});else if(a==="edit-link")openModal("link",{index:+x.dataset.index});else if(a==="delete-link")deleteLink(+x.dataset.index);else if(a==="import"){importInput.value="";importInput.click()}else if(a==="export-trip"){exportData(currentTrip(),`${slug(currentTrip().name)}.json`);toast("Viaje exportado")}else if(a==="restore-published")restorePublished();else if(a==="delete-trip")deleteTrip();else if(a==="install")installApp()}
function handleChange(e){const x=e.target,f=x.closest("form[data-form='activity']");if(x.dataset.check){const t=currentTrip(),item=(x.dataset.check==="packing"?t.packing:t.tasks).find(i=>i.id===x.dataset.id);if(item){item.done=x.checked;saveCurrent();render()}return}if(f&&["category","hasReturn","dayId","returnDayId"].includes(x.name))updateActivityForm(f,x.name)}
function handleSubmit(e){const f=e.target.closest("form[data-form]");if(!f)return;e.preventDefault();const fd=new FormData(f),v=Object.fromEntries(fd.entries()),t=currentTrip();
 if(f.dataset.form==="new-trip"){if(v.endDate<v.startDate)return toast("Fechas no válidas");const id=uniqueId(slug(v.name)),days=datesBetween(v.startDate,v.endDate).map((date,i)=>({id:uid("day"),date,name:`Día ${i+1}`})),trip=normalizeTrip({id,name:v.name.trim(),destination:v.destination.trim(),icon:destinationIcon(v.destination),currency:state.settings.defaultCurrency,days,activities:[],practical:Object.fromEntries(PRACTICAL.map(k=>[k,""])),links:[]});state.trips.set(id,trip);addCustomId(id);saveTrip(trip);syncCatalog();location.hash=`#viaje/${id}?vista=info`;return}
 if(f.dataset.form==="activity"){const old=t.activities.find(a=>a.id===v.id),cat=v.category,start=dayDate(t,v.dayId),endDate=v.endDate||start,badRange=(s,st,e,et)=>e<s||(e===s&&st&&et&&et<st);if(badRange(start,v.time,endDate,v.endTime))return toast("Fechas no válidas: el fin es anterior al inicio");
  let returnTrip=null;if(cat==="Transporte"&&v.hasReturn==="si"){const rs=dayDate(t,v.returnDayId),re=v.returnEndDate||rs,prev=old?.returnTrip;if(badRange(rs,v.returnTime,re,v.returnEndTime))return toast("Fechas de la vuelta no válidas");returnTrip={dayId:v.returnDayId,time:v.returnTime,endDate:re,endTime:v.returnEndTime,notes:v.returnNotes.trim(),location:v.returnLocation.trim(),mapQuery:v.returnMapQuery.trim(),completed:!!prev?.completed};if(prev&&prev.lat!=null&&prev.location===returnTrip.location&&prev.mapQuery===returnTrip.mapQuery){returnTrip.lat=prev.lat;returnTrip.lng=prev.lng}}
  const cur=String(v.currency||t.currency).trim().toUpperCase();if(!/^[A-Z]{3}$/.test(cur))return toast("Moneda no válida: usa un código de 3 letras (EUR, USD…)");let participants=fd.getAll("participants");if(participants.length===t.travelers.length)participants=[];
  const obj={currency:cur,participants,id:v.id||uid(cat==="Alojamiento"?"acc":"act"),dayId:v.dayId,time:v.time,endDate,endTime:v.endTime,title:v.title.trim(),category:cat,location:v.location.trim(),mapQuery:v.mapQuery.trim(),status:v.status,completed:v.completed==="true",notes:v.notes.trim(),locator:v.locator.trim(),bookingUrl:v.bookingUrl.trim(),links:parseLinks(v.links),estimated:+v.estimated||0,spent:+v.spent||0,linkedTo:v.linkedTo&&v.linkedTo!==v.id?v.linkedTo:null,returnTrip};
  if(old&&(old.location!==obj.location||old.mapQuery!==obj.mapQuery)){delete old.lat;delete old.lng}old?Object.assign(old,obj):t.activities.push(obj);if(obj.linkedTo)t.activities.forEach(x=>{if(x.linkedTo===obj.id)x.linkedTo=obj.linkedTo});sortActivities(t);finishSave(isStay(t,obj)?"Alojamiento guardado":"Actividad guardada");return}
 if(f.dataset.form==="day"){let d=t.days.find(d=>d.id===v.id);if(d){const oldDate=d.date;f.querySelectorAll(".edit-row").forEach(row=>{const a=findActivity(row.dataset.rowId),prev=dayDate(t,a.dayId);row.querySelectorAll("input,select").forEach(i=>a[i.name]=i.value);const now=dayDate(t,a.dayId);if(prev!==now&&(a.endDate===prev||a.endDate<now))a.endDate=now});Object.assign(d,{date:v.date,name:v.name.trim()});if(v.date!==oldDate)t.activities.forEach(a=>{if(a.dayId===d.id&&a.endDate===oldDate)a.endDate=v.date;if(a.returnTrip?.dayId===d.id&&a.returnTrip.endDate===oldDate)a.returnTrip.endDate=v.date})}else{d={id:uid("day"),date:v.date,name:v.name.trim()};t.days.push(d);state.currentDayId=d.id}sortDays(t);sortActivities(t);finishSave("Día guardado");return}
 if(f.dataset.form==="trip"){if(!v.startDate||!v.endDate||v.endDate<v.startDate)return toast("Fechas no válidas");const tz=v.timeZone.trim(),cur=v.currency.trim().toUpperCase();if(tz&&!validTZ(tz))return toast("Zona horaria no válida (ejemplo: Europe/Athens)");if(!/^[A-Z]{3}$/.test(cur))return toast("Moneda no válida: usa un código de 3 letras");
  const range=new Set(datesBetween(v.startDate,v.endDate)),drop=t.days.filter(d=>!range.has(d.date));if(drop.length){const ids=new Set(drop.map(d=>d.id)),acts=t.activities.filter(a=>ids.has(a.dayId)),rets=t.activities.filter(a=>a.returnTrip&&ids.has(a.returnTrip.dayId)&&!ids.has(a.dayId));if((acts.length||rets.length)&&!confirm(`Se eliminarán ${drop.length} día(s) (${drop.map(d=>shortDay(d.date)).join(", ")}) y ${acts.length} actividad(es):\n${acts.slice(0,12).map(a=>"• "+a.title).join("\n")}${acts.length>12?"\n…":""}${rets.length?`\nTambién se quitará la vuelta de: ${rets.map(a=>a.title).join(", ")}`:""}\n\n¿Continuar?`))return;const removed=new Set(acts.map(a=>a.id));t.days=t.days.filter(d=>range.has(d.date));t.activities=t.activities.filter(a=>!removed.has(a.id));t.activities.forEach(a=>{if(removed.has(a.linkedTo))a.linkedTo=null;if(a.returnTrip&&ids.has(a.returnTrip.dayId))a.returnTrip=null})}
  const have=new Set(t.days.map(d=>d.date)),added=[...range].filter(x=>!have.has(x)).map(date=>({id:uid("day"),date,name:""}));t.days.push(...added);sortDays(t);added.forEach(d=>d.name=`Día ${t.days.indexOf(d)+1}`);if(!t.days.some(d=>d.id===state.currentDayId))state.currentDayId=t.days[0]?.id;
  if(tz!==t.timeZone||v.destination.trim()!==t.destination)state.tzTried?.delete(t.id);Object.assign(t,{name:v.name.trim(),destination:v.destination.trim(),icon:v.icon.trim()||destinationIcon(v.destination),currency:cur,timeZone:tz});finishSave(added.length||drop.length?`Viaje guardado: ${added.length} día(s) añadidos, ${drop.length} eliminados`:"Viaje guardado");return}
 if(f.dataset.form==="traveler"){const name=v.name.trim();if(!name)return toast("Escribe un nombre");if(t.travelers.some(p=>p.id!==v.id&&p.name.toLowerCase()===name.toLowerCase()))return toast("Esa persona ya está en el viaje");const p=t.travelers.find(x=>x.id===v.id);p?p.name=name:t.travelers.push({id:uid("per"),name});finishSave("Persona guardada");return}
 if(f.dataset.form==="insurance"){if(v.startDate&&v.endDate&&v.endDate<v.startDate)return toast("Fechas de cobertura no válidas");const obj={id:v.id||uid("seg"),insurer:v.insurer.trim(),policyNumber:v.policyNumber.trim(),phone:v.phone.trim(),startDate:v.startDate,endDate:v.endDate,documentUrl:v.documentUrl.trim(),notes:v.notes.trim()},old=t.insurances.find(i=>i.id===v.id);old?Object.assign(old,obj):t.insurances.push(obj);finishSave("Seguro guardado");return}
 if(f.dataset.form==="packing-add"||f.dataset.form==="task-add"){const text=v.text.trim();if(!text)return;if(f.dataset.form==="packing-add"){state.lastPackCat=v.category;t.packing.push({id:uid("eq"),category:v.category,text,done:false})}else t.tasks.push({id:uid("tar"),text,done:false,dueDate:v.dueDate||""});saveCurrent();render();document.querySelector(`form[data-form="${f.dataset.form}"] input[name="text"]`)?.focus();return}
 if(f.dataset.form==="rates"){const rates={};Object.entries(v).forEach(([k,val])=>{if(k.startsWith("rate-")&&+val>0)rates[k.slice(5)]=+val});const nc=String(v.newCurrency||"").trim().toUpperCase();if(nc){if(!/^[A-Z]{3}$/.test(nc)||nc==="EUR")return toast("Código de moneda no válido");if(!(+v.newRate>0))return toast("Indica el valor en euros de 1 "+nc);rates[nc]=+v.newRate}t.rates=rates;finishSave("Tipos de cambio guardados");return}
 if(f.dataset.form==="import-new"){const name=v.name.trim(),inc=state.modal?.trip;if(!inc)return;if(!name)return toast("Escribe un nombre");if([...state.trips.values()].some(x=>x.name.trim().toLowerCase()===name.toLowerCase()))return toast("Ya hay un viaje con ese nombre");inc.id=uniqueId(slug(name));inc.name=name;delete inc.publishedVersion;storeImported(inc);nextImport();return}
 if(f.dataset.form==="practical"){t.practical[v.key]=v.value.trim();finishSave("Nota guardada");return}
 if(f.dataset.form==="link"){const obj={id:t.links[+v.index]?.id||uid("link"),label:v.label.trim(),url:v.url.trim()};+v.index>=0?t.links[+v.index]=obj:t.links.push(obj);finishSave("Enlace guardado");return}
 if(f.dataset.form==="default-currency"){state.settings.defaultCurrency=v.currency.trim().toUpperCase()||"EUR";localStorage.setItem(SETTINGS_KEY,JSON.stringify(state.settings));state.modal=null;render();toast("Moneda guardada")}}
function openModal(type,extra={}){state.modal={type,...extra};render()}
function finishSave(msg){saveCurrent();state.modal=null;syncCatalog();render();toast(msg)}
function duplicateActivity(id){const a=findActivity(id);if(!a)return;const copy=clone(a);copy.id=uid("act");copy.title+= " (copia)";currentTrip().activities.push(copy);sortActivities(currentTrip());saveCurrent();state.modal={type:"day",id:copy.dayId};render();toast("Actividad duplicada")}
function deleteActivity(id){if(!confirm("¿Eliminar actividad?"))return;const t=currentTrip();t.activities=t.activities.filter(a=>a.id!==id);t.activities.forEach(a=>{if(a.linkedTo===id)a.linkedTo=null});saveCurrent();if(state.modal?.type==="day")render();else{state.modal=null;render()}toast("Actividad eliminada")}
function deleteDay(id){const t=currentTrip();if(t.days.length===1)return toast("El viaje debe tener al menos un día");if(!confirm("¿Eliminar el día y sus actividades?"))return;t.days=t.days.filter(d=>d.id!==id);const removed=new Set(t.activities.filter(a=>a.dayId===id).map(a=>a.id));t.activities=t.activities.filter(a=>a.dayId!==id);t.activities.forEach(a=>{if(removed.has(a.linkedTo))a.linkedTo=null;if(a.returnTrip?.dayId===id)a.returnTrip=null});sortDays(t);state.currentDayId=t.days[0].id;finishSave("Día eliminado")}
function deleteTraveler(id){const t=currentTrip(),p=t.travelers.find(x=>x.id===id);if(!p||!confirm(`¿Quitar a ${p.name} del viaje?`))return;t.travelers=t.travelers.filter(x=>x.id!==id);t.activities.forEach(a=>{a.participants=(a.participants||[]).filter(x=>x!==id);if(a.participants.length===t.travelers.length)a.participants=[]});finishSave("Persona eliminada")}
function deleteLink(i){if(!confirm("¿Eliminar enlace?"))return;currentTrip().links.splice(i,1);finishSave("Enlace eliminado")}
function budget(t){const out={estimated:0,spent:0,byCategory:{},byDay:{},byPerson:{},missing:[]},miss=new Set(),people=(t.travelers||[]).map(p=>p.id);Object.keys(CATEGORIES).forEach(c=>out.byCategory[c]={estimated:0,spent:0});t.days.forEach(d=>out.byDay[d.id]={estimated:0,spent:0});people.forEach(id=>out.byPerson[id]={estimated:0,spent:0});
 t.activities.filter(a=>!a.linkedTo).forEach(a=>{const cur=a.currency||t.currency||"EUR",e=toEUR(t,a.estimated,cur),s=toEUR(t,a.spent,cur);if(e==null||s==null){if(+a.estimated||+a.spent)miss.add(cur);return}out.estimated+=e;out.spent+=s;const c=out.byCategory[a.category]||out.byCategory.Otro;c.estimated+=e;c.spent+=s;if(out.byDay[a.dayId]){out.byDay[a.dayId].estimated+=e;out.byDay[a.dayId].spent+=s}const who=(a.participants?.length?a.participants:people).filter(id=>out.byPerson[id]);who.forEach(id=>{out.byPerson[id].estimated+=e/who.length;out.byPerson[id].spent+=s/who.length})});
 out.missing=[...miss];return out}
async function importJSONFile(){const file=importInput.files?.[0];if(!file)return;let trips;try{const p=JSON.parse(await file.text());trips=(Array.isArray(p.trips)?p.trips:[p]).map(raw=>normalizeTrip(raw))}catch(e){console.error(e);return toast("JSON no válido")}state.importQueue=trips;state.importDone=[];nextImport()}
function nextImport(){const t=state.importQueue?.shift();if(!t){const done=state.importDone||[];state.importQueue=null;state.importDone=[];state.modal=null;syncCatalog();render();if(done.length)toast(done.length===1?`Viaje importado: ${done[0]}`:`${done.length} viajes importados`);return}if(state.trips.has(t.id)){state.modal={type:"import-conflict",trip:t};render();return}storeImported(t);nextImport()}
function storeImported(t){state.trips.set(t.id,t);saveTrip(t);if(!state.published.has(t.id))addCustomId(t.id);(state.importDone||=[]).push(t.name)}
function stable(v){return JSON.stringify(v??null,(k,x)=>x&&typeof x==="object"&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(y=>[y,x[y]])):x)}
function stamp(t){if(t.updatedAt){const d=new Date(t.updatedAt);if(!isNaN(d))return new Intl.DateTimeFormat("es-ES",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(d).replace(".","")}return t.publishedVersion?`Versión publicada ${t.publishedVersion}`:"Sin fecha"}
const DIFF_FIELDS={dayId:"día",time:"hora",endDate:"fecha fin",endTime:"hora fin",title:"título",category:"categoría",status:"estado",location:"ubicación",mapQuery:"mapa",notes:"notas",locator:"localizador",bookingUrl:"documento",links:"enlaces",estimated:"importes",spent:"importes",linkedTo:"incluida en",returnTrip:"vuelta",completed:"completada",currency:"moneda",participants:"participantes"};
function compareTrips(cur,inc){const bc=budget(cur),bi=budget(inc),rows=[["Última modificación",stamp(cur),stamp(inc)],["Fechas",formatTripRange(cur.startDate,cur.endDate),formatTripRange(inc.startDate,inc.endDate)],["Actividades",String(cur.activities.length),String(inc.activities.length)],["Reservas",String(cur.activities.filter(isBooking).length),String(inc.activities.filter(isBooking).length)],["Personas",peopleLabel(cur)||"—",peopleLabel(inc)||"—"],["Estimado / Gastado",`${money(bc.estimated,"EUR")} / ${money(bc.spent,"EUR")}`,`${money(bi.estimated,"EUR")} / ${money(bi.spent,"EUR")}`]];
 const diffs=[],mine=new Map(cur.activities.map(a=>[a.id,a])),theirs=new Map(inc.activities.map(a=>[a.id,a]));
 const tripParts=[["name","nombre"],["destination","destino"],["icon","icono"],["currency","moneda"],["days","días"],["practical","notas prácticas"],["links","enlaces del viaje"],["travelers","personas"],["timeZone","zona horaria"],["rates","tipos de cambio"],["insurances","seguro"],["packing","equipaje"],["tasks","tareas"]].filter(([k])=>stable(cur[k])!==stable(inc[k])).map(([,l])=>l);if(tripParts.length)diffs.push(`✏️ Viaje: ${tripParts.join(", ")}`);
 inc.activities.forEach(a=>{const b=mine.get(a.id);if(!b)return diffs.push(`➕ Solo en el archivo: ${a.title}`);const f=[...new Set(Object.keys(DIFF_FIELDS).filter(k=>stable(a[k])!==stable(b[k])).map(k=>DIFF_FIELDS[k]))];if(f.length)diffs.push(`✏️ ${a.title}: ${f.join(", ")}`)});
 cur.activities.forEach(a=>{if(!theirs.has(a.id))diffs.push(`➖ Solo en la app: ${a.title}`)});
 const x=cur.updatedAt,y=inc.updatedAt;let notice;if(!diffs.length)notice="Las dos versiones tienen el mismo contenido.";else if(x&&y)notice=y>x?"El archivo es más reciente que tu versión.":y<x?"El archivo es más antiguo que tu versión.":"Las dos versiones tienen la misma fecha de modificación.";else if(!x&&!y&&cur.publishedVersion&&inc.publishedVersion&&cur.publishedVersion!==inc.publishedVersion)notice=inc.publishedVersion>cur.publishedVersion?"El archivo es más reciente que tu versión.":"El archivo es más antiguo que tu versión.";else notice="No se puede saber cuál es más reciente: una de las versiones no tiene fecha de modificación.";
 return{rows,diffs,notice}}
function importConflictModal(inc){const cur=state.trips.get(inc.id);if(!cur)return"";const c=compareTrips(cur,inc),shown=c.diffs.slice(0,10),more=c.diffs.length-shown.length;return modal("Este viaje ya existe",`<div class="import-compare"><p>Ya tienes «${esc(cur.name)}». Revisa las diferencias antes de importar.</p><div class="compare-table-wrap"><table class="compare-table"><thead><tr><th></th><th>En la app</th><th>En el archivo</th></tr></thead><tbody>${c.rows.map(r=>`<tr><th>${esc(r[0])}</th><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join("")}</tbody></table></div><p><strong>${esc(c.notice)}</strong></p>${shown.length?`<ul class="diff-list">${shown.map(d=>`<li>${esc(d)}</li>`).join("")}${more>0?`<li>y ${more} más</li>`:""}</ul>`:""}<div class="btn-row"><button class="secondary-btn" data-action="import-cancel">Cancelar</button><button class="secondary-btn" data-action="import-as-new">Guardar como viaje diferente</button><button class="danger-btn" data-action="import-replace">Reemplazar por el archivo</button></div></div>`)}
function importNewModal(inc){return modal("Guardar como viaje diferente",`<form data-form="import-new" class="form-grid"><p>El archivo se guardará como un viaje nuevo y «${esc(inc.name)}» no cambiará.</p>${field("Nombre del nuevo viaje","name","text",`${inc.name} (importado)`,true)}<div class="btn-row"><button type="button" class="secondary-btn" data-action="import-back">Volver</button><button class="primary-btn">Guardar</button></div></form>`)}
function exportData(data,name){downloadFile(JSON.stringify(data,null,2),name,"application/json")}
function restorePublished(){const t=currentTrip(),p=state.published.get(t.id);if(!p||!confirm("¿Restaurar la versión publicada?"))return;localStorage.removeItem(STORAGE_PREFIX+t.id);state.trips.set(t.id,clone(p));state.currentDayId=p.days[0]?.id;state.modal=null;syncCatalog();render();toast("Versión publicada restaurada")}
function deleteTrip(){const t=currentTrip();if(!confirm(`¿Eliminar ${t.name}?`))return;localStorage.removeItem(STORAGE_PREFIX+t.id);localStorage.setItem(CUSTOM_KEY,JSON.stringify(loadJSON(CUSTOM_KEY,[]).filter(id=>id!==t.id)));state.trips.delete(t.id);if(state.published.has(t.id))state.trips.set(t.id,clone(state.published.get(t.id)));syncCatalog();location.hash=""}
async function installApp(){if(state.deferredInstall){state.deferredInstall.prompt();await state.deferredInstall.userChoice;state.deferredInstall=null;render()}}
function currentTrip(){return state.trips.get(state.currentTripId)}function currentDay(t=currentTrip()){return t.days.find(d=>d.id===state.currentDayId)||t.days[0]}function findActivity(id){return currentTrip()?.activities.find(a=>a.id===id)}
function saveCurrent(){const t=currentTrip();t.updatedAt=new Date().toISOString();sortDays(t);sortActivities(t);saveTrip(t);syncCatalog()}function saveTrip(t){try{localStorage.setItem(STORAGE_PREFIX+t.id,JSON.stringify(t))}catch{toast("No se pudo guardar")}}function addCustomId(id){const a=loadJSON(CUSTOM_KEY,[]);if(!a.includes(id)){a.push(id);localStorage.setItem(CUSTOM_KEY,JSON.stringify(a))}}
function sortDays(t){t.days.sort((a,b)=>a.date.localeCompare(b.date));t.startDate=t.days[0]?.date;t.endDate=t.days.at(-1)?.date}function sortActivities(t){const order=Object.fromEntries(t.days.map((d,i)=>[d.id,i]));t.activities.sort((a,b)=>(order[a.dayId]??999)-(order[b.dayId]??999)||String(a.time||"99:99").localeCompare(String(b.time||"99:99")))}
function addDays(s,n){if(!s)return"";const d=new Date(`${s}T12:00:00`);d.setDate(d.getDate()+n);return localISO(d)}function nextDayDate(t){const d=new Date(`${t.days.at(-1)?.date||localISO(new Date())}T12:00:00`);d.setDate(d.getDate()+1);return localISO(d)}function datesBetween(a,b){const out=[],d=new Date(`${a}T12:00:00`),end=new Date(`${b}T12:00:00`);for(;d<=end;d.setDate(d.getDate()+1))out.push(localISO(d));return out}
function destinationIcon(s){s=String(s).toLowerCase();if(/atenas|grecia|egina/.test(s))return"🇬🇷";if(/lisboa|porto|portugal/.test(s))return"🇵🇹";if(/parís|francia/.test(s))return"🇫🇷";if(/roma|italia|milán/.test(s))return"🇮🇹";if(/londres|reino unido/.test(s))return"🇬🇧";if(/madrid|barcelona|sevilla|españa/.test(s))return"🇪🇸";if(/tokio|japón/.test(s))return"🇯🇵";if(/playa|isla|costa/.test(s))return"🏝️";if(/montaña|sierra/.test(s))return"⛰️";return"🧭"}
function formatHomeRange(a,b){const A=dateParts(a),B=dateParts(b);if(A.y===B.y&&A.m===B.m)return`${A.d}–${B.d} ${A.mon} ${A.y}`;if(A.y===B.y)return`${A.d} ${A.mon}–${B.d} ${B.mon} ${A.y}`;return`${A.d} ${A.mon} ${A.y}–${B.d} ${B.mon} ${B.y}`}
function formatTripRange(a,b){const A=dateParts(a),B=dateParts(b);return A.m===B.m?`${A.d}–${B.d} ${A.mon}`:`${A.d} ${A.mon}–${B.d} ${B.mon}`}
function dateParts(s){const d=new Date(`${s}T12:00:00`);return{d:d.getDate(),m:d.getMonth(),y:d.getFullYear(),mon:new Intl.DateTimeFormat("es-ES",{month:"short"}).format(d).replace(".","")}}
function formatDayDate(s){return new Intl.DateTimeFormat("es-ES",{weekday:"short",day:"numeric",month:"short"}).format(new Date(`${s}T12:00:00`)).replace(/\./g,"")}function shortDay(s){return new Intl.DateTimeFormat("es-ES",{day:"numeric",month:"short"}).format(new Date(`${s}T12:00:00`)).replace(".","")}
function routeUrl(stops){const clean=stops.map(stripMapUrl).filter(Boolean);if(clean.length===1)return mapSearch(clean[0]);const origin=clean[0],destination=clean.at(-1),waypoints=clean.slice(1,-1).join("|");return`https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(destination)}${waypoints?`&waypoints=${encodeURIComponent(waypoints)}`:""}`}
function directionsButton(dest,label,origin=""){if(!dest)return"";dest=stripMapUrl(dest);origin=stripMapUrl(origin);const url=`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(dest)}${origin?`&origin=${encodeURIComponent(origin)}`:""}`;return`<a href="${url}" target="_blank" rel="noopener">📍 ${label}</a>`}function mapSearch(q){return`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`}
function stripMapUrl(v){if(!v)return"";try{const u=new URL(v);return u.searchParams.get("query")||u.searchParams.get("destination")||v}catch{return v}}
function parseLinks(s){return String(s||"").split(/\n+/).map(x=>x.trim()).filter(Boolean).map(x=>{const i=x.indexOf("|");return i<0?{label:"Enlace",url:x}:{label:x.slice(0,i).trim()||"Enlace",url:x.slice(i+1).trim()}}).filter(x=>safeUrl(x.url)!=="#")}
function practicalIcon(k){return({"transporte local":"🚌","clima y equipaje":"🧳","gastronomía":"🍽️","compras":"🛍️","seguridad y salud":"🩺","plan alternativo":"🔁","nota libre":"📝"})[k]||"📝"}function titleCase(s){return s.charAt(0).toUpperCase()+s.slice(1)}
function money(v,c){try{return new Intl.NumberFormat("es-ES",{style:"currency",currency:c||"EUR",maximumFractionDigits:2}).format(+v||0)}catch{return`${(+v||0).toFixed(2)} ${c}`}}function safeUrl(v){try{const u=new URL(v,location.href);return["http:","https:"].includes(u.protocol)?u.href:"#"}catch{return"#"}}
function esc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c])}function attr(v){return esc(v)}function nl2br(v){return esc(v).replace(/\n/g,"<br>")}function slug(v){return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"viaje"}function uid(p){return`${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`}function uniqueId(base){let id=base||"viaje",i=2;while(state.trips.has(id))id=`${base}-${i++}`;return id}function clone(v){return JSON.parse(JSON.stringify(v))}function loadJSON(k,f){try{const v=localStorage.getItem(k);return v?JSON.parse(v):f}catch{return f}}function localISO(d){return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function toast(m){const r=document.querySelector("#toast-region");if(!r)return;const x=document.createElement("div");x.className="toast";x.textContent=m;r.appendChild(x);setTimeout(()=>x.remove(),2600)}function registerServiceWorker(){if("serviceWorker"in navigator&&location.protocol.startsWith("http"))navigator.serviceWorker.register("sw.js").catch(console.warn)}
